INSERT INTO animes (id, mal_id, slug, title, title_english, title_japanese, synopsis, synopsis_short, poster, banner, status, type, year, season, studio, rating, score, episodes, duration, is_featured, is_trending, is_new_update, created_at, updated_at) VALUES ('sokuja-ao-no-hako', NULL, 'ao-no-hako', 'Ao no Hako', 'Ao no Hako', 'Blue Box, Kotak Biru', 'Taiki Inomata, siswa tahun ketiga SMP, bersekolah di Akademi Eimei, sekolah terpadu dengan program olahraga utama. Tergabung dalam tim bulu tangkis SMA, Taiki berusaha mengikuti latihan terbuka sedini mungkin. Tapi tidak peduli seberapa awal dia pergi, dia selalu berada di urutan kedua di gimnasium.', 'Taiki Inomata, siswa tahun ketiga SMP, bersekolah di Akademi Eimei, sekolah terpadu dengan program olahraga utama. Terga...', 'https://gbr.sokuja.uk/wp-content/uploads/2024/09/SOKUJA-Ao_no_Hako-6.jpg', 'https://gbr.sokuja.uk/wp-content/uploads/2024/09/SOKUJA-Ao_no_Hako-6.jpg', 'completed', 'TV', 2024, 'Spring', 'Sokuja Studio', 'PG-13', 8.36, 24, 24, FALSE, TRUE, FALSE, '2026-08-29T13:32:31.071Z', '2026-08-29T13:32:31.071Z') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, score = EXCLUDED.score, poster = EXCLUDED.poster;
INSERT INTO animes (id, mal_id, slug, title, title_english, title_japanese, synopsis, synopsis_short, poster, banner, status, type, year, season, studio, rating, score, episodes, duration, is_featured, is_trending, is_new_update, created_at, updated_at) VALUES ('sokuja-ao-no-orchestra', NULL, 'ao-no-orchestra', 'Ao no Orchestra', 'Ao no Orchestra', 'The Blue Orchestra, 青のオーケストラ, orkestra biru', 'Hajime Aono dulu hidup untuk suara permainan biolanya. Sejak kecil, dia mengagumi ayah pemain biolanya yang terkenal di dunia, yang menginspirasinya untuk memainkan alat musik itu sendiri.', 'Hajime Aono dulu hidup untuk suara permainan biolanya. Sejak kecil, dia mengagumi ayah pemain biolanya yang terkenal di ...', 'https://gbr.sokuja.uk/wp-content/uploads/2023/04/1681048803-8597-133754.jpg', 'https://gbr.sokuja.uk/wp-content/uploads/2023/04/1681048803-8597-133754.jpg', 'completed', 'TV', 2023, 'Spring', 'Sokuja Studio', 'PG-13', 7.15, 23, 24, FALSE, TRUE, FALSE, '2026-08-29T13:32:31.531Z', '2026-08-29T13:32:31.531Z') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, score = EXCLUDED.score, poster = EXCLUDED.poster;
